# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student


def _sort_key(student: Student):
    name = student.display_name.lower()
    return (name, student.student_id)


def _require_emails(students: List[Student]) -> None:
    for student in students:
        if not student.email:
            name = student.display_name
            raise ValueError(f"No email for {name}")


def _row(student: Student, name_w: int, sec_w: int) -> str:
    name = f"{student.display_name:<{name_w}}"
    section = f"{student.section:<{sec_w}}"
    return f"{name}  {section}  {student.email}"


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    ordered = sorted(students, key=_sort_key)
    if not ordered:
        raise ValueError("No students given")
    _require_emails(ordered)
    name_w = max(len(s.display_name) for s in ordered)
    sec_w = max(len(s.section) for s in ordered)
    return [_row(s, name_w, sec_w) for s in ordered]
